from six import string_types

from .throughput_measurement import ThroughputMeasurement, ThroughputException


class ThroughputAnalyze(object):
    """
    Throughput analizer
    """

    @staticmethod
    def expected_bler_for_cell_should_not_exceed(cell, direction, margin=10):
        """
        Verifies that given throughput for given ue is achieved. Raises an exception when the throughput is lower than
         expected with given margin.
        :param ue_id: egate UE id
        :param throughput: expected throughput in Mbps
        :param margin: possible margin of error
        :param direction: 'dl' or 'ul'
        :param selection_type: 'current' or 'minimum' or 'maximum' or 'average'
        :param layer: 'mac' or 'physical'
        :param retry:  number of retry after incorrect read egate output
        """
        bler_percentage = ThroughputMeasurement().get_cell_bler(cell, direction, retry=3)
        if isinstance(margin, string_types) and '%' in margin:
            float_margin = margin.replace('%', '')
            float_margin = float(float_margin)
        else:
            float_margin = float(margin)
        if bler_percentage >= float(float_margin):
            raise ThroughputException(
                '{} Cell bler {} % is higher than allowed: {} %'.format(
                    direction.upper(), bler_percentage, float_margin
                )
            )
        return bler_percentage

    @staticmethod
    def expected_throughput_for_ue_should_be_reached(
        ue_id, throughput, margin, direction, selection_type, layer, scells, retry, precision=2, cell_group=None
    ):
        """
        Verifies that given throughput for given ue is achieved. Raises an exception when the throughput is lower than
         expected with given margin.
        :param ue_id: egate UE id
        :param throughput: expected throughput in Mbps
        :param margin: possible margin of error
        :param direction: 'dl' or 'ul'
        :param selection_type: 'current' or 'minimum' or 'maximum' or 'average'
        :param layer: 'mac' or 'physical'
        :param retry:               number of retry after incorrect read egate output
        """
        throughput_in_mbps = ThroughputMeasurement().get_ue_throughput(
            ue_id, selection_type, direction, layer, scells, retry, precision, cell_group
        )
        if isinstance(margin, string_types) and '%' in margin:
            float_margin = margin.replace('%', '')
            float_margin = float(float_margin) * 0.01 * float(throughput)
        else:
            float_margin = float(margin)
        if throughput_in_mbps + float(float_margin) < float(throughput):
            raise ThroughputException(
                '{} UE throughput ({} Mbps) is lower than expected: {} Mbps'.format(
                    direction.upper(), throughput_in_mbps, throughput
                )
            )

    @staticmethod
    def expected_throughput_for_list_of_ues_should_be_reached(
        ues_list, throughput, margin, direction, selection_type, layer, scells, retry, precision=2
    ):
        """
        Verifies that given throughput for given ue is achieved. Raises an exception when the throughput is lower than
         expected with given margin.
        :param ues_list: list of egate UEs
        :param throughput: expected throughput in Mbps
        :param margin: possible margin of error
        :param direction: 'dl' or 'ul'
        :param selection_type: 'current' or 'minimum' or 'maximum' or 'average'
        :param layer: 'mac' or 'physical'
        :param retry: number of retry after incorrect read egate output
        """
        for ue in ues_list:
            ThroughputAnalyze.expected_throughput_for_ue_should_be_reached(
                ue, throughput, margin, direction, selection_type, layer, scells, retry, int(precision)
            )

    @staticmethod
    def expected_throughput_for_cell_should_be_reached(
        cell_id, throughput, margin, direction, selection_type, layer, enb_id, retry
    ):
        """
        Verifies that given throughput for given cell is achieved.
        Raises an exception when the throughput is lower than
         expected with given margin.
        :param cell_id: egate cell id
        :param throughput: expected throughput in Mbps
        :param margin: possible margin of error
        :param direction: 'dl' or 'ul'
        :param selection_type: 'current' or 'minimum' or 'maximum' or 'average'
        :param layer: 'mac' or 'physical' or 'data'
        :param retry: number of retry after incorrect read egate output
        :param enb_id: id of enb
        """
        if layer == 'data':
            throughput_in_mbps = ThroughputMeasurement().get_cell_throughput_for_data_layer(
                cell_id, direction, layer, enb_id, retry)
        else:
            throughput_in_mbps = ThroughputMeasurement().get_cell_throughput(
                cell_id, selection_type, direction, layer, retry)

        if isinstance(margin, string_types) and '%' in margin:
            float_margin = margin.replace('%', '')
            float_margin = float(float_margin) * 0.01 * float(throughput)
        else:
            float_margin = float(margin)
        if throughput_in_mbps + float(float_margin) < float(throughput):
            raise ThroughputException(
                '{} Cell throughput ({} Mbps) is lower than expected: {} Mbps'.format(
                    direction.upper(), throughput_in_mbps, throughput
                )
            )

    @staticmethod
    def expected_throughput_for_bearer_should_be_reached(ue, bearer, throughput, direction, selection_type, margin,
                                                         retry):
        """
        Verifies that given throughput for given bearer is achieved.
        Raises an exception when the throughput is lower than
        expected with given margin.
        :param ue: egate ue id
        :param bearer: egate bearer id
        :param throughput: expected throughput in Mbps
        :param margin: possible margin of error
        :param direction: 'dl' or 'ul'
        :param selection_type: 'minimum' or 'maximum' or 'average' (default average)
        :param retry: number of retry after incorrect read egate output
        """
        throughput_in_mbps = ThroughputMeasurement().get_bearer_throughput_for_data_layer(
            ue, bearer, direction, selection_type=selection_type, retry=retry)

        if isinstance(margin, string_types) and '%' in margin:
            float_margin = margin.replace('%', '')
            float_margin = float(float_margin) * 0.01 * float(throughput)
        else:
            float_margin = float(margin)
        if throughput_in_mbps + float(float_margin) < float(throughput):
            raise ThroughputException(
                '{} Cell throughput ({} Mbps) is lower than expected: {} Mbps'.format(
                    direction.upper(), throughput_in_mbps, throughput
                )
            )

    @staticmethod
    def expected_throughput_based_on_bearer_stats_should_be_reached(ue, pdu, bearer, throughput, direction, selection_type, margin,
                                                                    retry, **kwargs):
        """
        Verifies that given throughput based on egate command bearer_stats is achieved.
        Raises an exception when the throughput is lower than
        expected with given margin.
        :param ue: egate ue id
        :param pdu: egate pdu id, should be set as None if not necessary in egate command bearer_stats
        :param bearer: egate bearer id, should be set as None if not necessary in egate command bearer_stats
        :param throughput: expected throughput in Mbps
        :param margin: possible margin of error
        :param direction: 'dl' or 'ul'
        :param selection_type: 'minimum' or 'maximum' or 'average' (default average)
        :param retry: number of retry after incorrect read egate output
        :param kwargs: other arguments necessary for egate bearer_stats command,
        Be aware that function doesn't check if Your parameters are correct
        """
        throughput_in_mbps = ThroughputMeasurement().get_bearer_throughput_for_data_layer_with_additional_params(
            ue, pdu, bearer, direction, selection_type=selection_type, retry=retry, **kwargs)

        if isinstance(margin, string_types) and '%' in margin:
            float_margin = margin.replace('%', '')
            float_margin = float(float_margin) * 0.01 * float(throughput)
        else:
            float_margin = float(margin)
        if throughput_in_mbps + float(float_margin) < float(throughput):
            raise ThroughputException(
                '{} Cell throughput ({} Mbps) is lower than expected: {} Mbps'.format(
                    direction.upper(), throughput_in_mbps, throughput
                )
            )

    @staticmethod
    def throughput_on_all_ue_bearers_is_equal(ue_id, selection_type, direction, throughput, margin, retry=0):
        """
        Checks if selected throughput on all ue bearers is equal in given margin
        :param ue_id:                   ue_id
        :param direction:               Direction 'ul' or 'dl', if not given starts traffic in both
        :param selection_type:          'current' or 'minimum' or 'maximum' or 'average'
        :param throughput:              expected throughput
        :param margin:                  possible margin of error
        :param retry:                   number of retry after incorrect read egate output
        """
        margin_range = ThroughputAnalyze._calculate_allowed_throughput_range(str(margin), str(throughput))
        directions = ('ul', 'dl') if not direction else (direction,)
        throughputs = (
            ThroughputMeasurement().get_bearers_throughput(ue_id, selection_type, d, retry) for d in directions
        )
        ThroughputAnalyze._assert_range_on_all_ue_bearers(margin_range, throughputs)

    @staticmethod
    def _convert_to_mbps(str_value):
        value = float(str_value.strip('mkbps'))
        return value / 1024 if 'kbps' in str_value else value

    @staticmethod
    def _assert_range_on_all_ue_bearers(margin_range, bearers_stats):
        for bearer in bearers_stats:
            if not all(min(margin_range) <= t <= max(margin_range) for t in list(bearer.values())):  # noqa: C419
                raise ThroughputException(
                    'Bearer {} throughput is not in range <{},{}>'.format(bearer, min(margin_range), max(margin_range))
                )

    @staticmethod
    def _calculate_allowed_throughput_range(margin, throughput):
        throughput = ThroughputAnalyze._convert_to_mbps(throughput)
        if '%' in margin:
            margin = float(margin.strip('%')) / 100
            return throughput * (1 - margin), throughput * (1 + margin)
        else:
            margin = ThroughputAnalyze._convert_to_mbps(margin)
            return throughput - margin, throughput + margin
